CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), day date NOT NULL UNIQUE, topic text NOT NULL, language text NOT NULL, content jsonb NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, module text NOT NULL CHECK(module IN ('reading','memory','thinking','speech')), question_index integer NOT NULL DEFAULT 0, answer text NOT NULL DEFAULT '', score integer NOT NULL CHECK(score BETWEEN 0 AND 100), feedback text NOT NULL DEFAULT '', metrics jsonb NOT NULL DEFAULT '{}', created_at timestamptz DEFAULT now(), UNIQUE(session_id,module,question_index));
CREATE INDEX IF NOT EXISTS attempts_session_idx ON attempts(session_id);
